-- Real songs from Spotify: ~2,900 popular tracks (popularity 70+), added after
-- the hand-made catalog in data_inserts.sql. Run this right after data_inserts.sql.
--
-- Source: data/source/spotify_tracks_pop70.csv, which is the Spotify Tracks Dataset
-- (huggingface.co/datasets/maharshipandya/spotify-tracks-dataset) filtered to
-- popularity >= 70. Songs already in data_inserts.sql weren't added again.
-- Spotify tags songs with ~100 small genres ("alt-rock", "k-pop", "deep-house", ...),
-- so we grouped those into our broad genres and kept up to 2 per song.
-- Album covers come from data/fetch_album_covers.py.


