SELECT setval(pg_get_serial_sequence('genre',  'genre_id'),  (SELECT max(genre_id)  FROM genre));
SELECT setval(pg_get_serial_sequence('artist', 'artist_id'), (SELECT max(artist_id) FROM artist));
